package eu.karelhovorka.zpevnik.formatter

import com.google.gson.JsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * html/before: rendered by the old parser (chords 351afad), frozen, never regenerated by tests, with the
 *   stylesheet of that version in before/style.css.
 *   To add songs: check out 351afad in a worktree, copy HtmlSnapshots.kt (only) and the songs there,
 *   and run its HtmlSnapshotWriter with HTML_SNAPSHOT_DIR pointing to html/before.
 * html/after: rendered by the current code; run with UPDATE_GOLDEN=1 after an intended change.
 * What a reader sees in the two depends on CSS (display settings hide by class), so the visible text is
 * compared in Chrome by tools/visible-text/check.mjs; every difference must be in html/reviewed-changes.json.
 */
class HtmlDisplayTest {

    private val htmlDir = File(HtmlSnapshots.root(), "src/jvmTest/resources/html")

    private fun read(set: String): Map<String, String> {
        val dir = File(htmlDir, set)
        return dir.walk().filter { it.isFile && it.extension == "html" }.associate { it.relativeTo(dir).path to it.readText() }
    }

    @Test
    fun currentHtmlMatchesAfterSnapshots() {
        val after = File(htmlDir, "after")
        if (System.getenv("UPDATE_GOLDEN") == "1") {
            after.deleteRecursively()
            HtmlSnapshots.writeAll(after)
        }
        val expected = read("after")
        val actual = HtmlSnapshots.renderAll()
        assertEquals(expected.keys, actual.keys)
        for ((path, html) in actual) {
            assertEquals(path, expected[path], html)
        }
    }

    @Test
    fun beforeAndAfterCoverSameSnapshots() {
        assertTrue(read("before").isNotEmpty())
        assertEquals(read("before").keys, read("after").keys)
        assertTrue(File(htmlDir, "before/style.css").isFile)
    }

    @Test
    fun reviewedChangesReferToSnapshots() {
        val snapshots = read("after").keys
        val changes = JsonParser.parseString(File(htmlDir, "reviewed-changes.json").readText()).asJsonObject.getAsJsonArray("changes")
        assertTrue(changes.size() > 0)
        for (change in changes.map { it.asJsonObject }) {
            val song = change.get("song").asString
            assertTrue(change.get("reason").asString.isNotBlank())
            for (layout in change.getAsJsonArray("layouts").map { it.asString }) {
                for (variant in change.getAsJsonArray("variants").map { it.asString }) {
                    assertTrue("$song/$layout-$variant.html", "$song/$layout-$variant.html" in snapshots)
                }
            }
        }
    }
}
